 /* bit tr: the new patch is an edit of the last (ui_fm6op.c): its trim stays */
/* ------------------------------------------------------- patch formats --- */
/* the highest value of each byte of the 155-byte voice */
static uint32_t fm6_max(uint32_t i)
{
    static const uint8_t OPMAX[21] = {99, 99, 99, 99, 99, 99, 99, 99, 99, 99, 99, 3, 3, 7, 3, 7, 99, 1, 31, 99, 14};
    static const uint8_t VMAX[19] = {99, 99, 99, 99, 99, 99, 99, 99, 31, 7, 1, 99, 99, 99, 99, 1, 5, 7, 48};
    if (i < 126u)
        return OPMAX[i % 21u];
    if (i < FP_NAME)
        return VMAX[i - 126u];
    return 126u;
}
/* every value inside its range (a name byte outside 32..126 becomes a space) */
static void fm6_sanitize(uint8_t *v)
{
    uint32_t i;
    for (i = 0; i < FP_SIZE; i++) {
        if (i >= FP_NAME)
            v[i] = v[i] < 32u || v[i] > 126u ? ' ' : v[i];
        else if (v[i] > fm6_max(i))
            v[i] = (uint8_t)fm6_max(i);
    }
    v[FP_SIZE] = 0;
}
/* 128-byte packed record (the 32-voice bank's) -> 155-byte voice; bits a record does not use are ignored */
static void fm6_unpack(const uint8_t *b, uint8_t *v)
{
    uint32_t k, i;
    for (k = 0; k < 6u; k++) {
        const uint8_t *o = b + k * 17u;
        uint8_t *d = v + k * FP_OP;
        for (i = 0; i < 11u; i++)
            d[i] = o[i] & 0x7Fu;
        d[FP_LC] = o[11] & 3u;
        d[FP_RC] = (o[11] >> 2) & 3u;
        d[FP_RS] = o[12] & 7u;
        d[FP_DET] = (o[12] >> 3) & 15u;
        d[FP_AMS] = o[13] & 3u;
        d[FP_KVS] = (o[13] >> 2) & 7u;
        d[FP_OL] = o[14] & 0x7Fu;
        d[FP_MODE] = o[15] & 1u;
        d[FP_FC] = (o[15] >> 1) & 31u;
        d[FP_FF] = o[16] & 0x7Fu;
    }
    for (i = 0; i < 9u; i++)
        v[FP_PR1 + i] = b[102 + i] & 0x7Fu; /* pitch EG, algorithm */
    v[FP_ALG] &= 31u;
    v[FP_FB] = b[111] & 7u;
    v[FP_OKS] = (b[111] >> 3) & 1u;
    for (i = 0; i < 4u; i++)
        v[FP_LFS + i] = b[112 + i] & 0x7Fu;
    v[FP_LKS] = b[116] & 1u;
    v[FP_LFW] = (b[116] >> 1) & 7u;
    v[FP_LPMS] = (b[116] >> 4) & 7u;
    v[FP_TRNSP] = b[117] & 0x7Fu;
    for (i = 0; i < 10u; i++)
        v[FP_NAME + i] = b[118 + i] & 0x7Fu;
    fm6_sanitize(v);
}
/* 155-byte voice -> 128-byte packed record (7-bit bytes: it travels in SysEx as it is) */
static void fm6_pack(const uint8_t *v, uint8_t *b)
{
    uint32_t k, i;
    for (k = 0; k < 6u; k++) {
        const uint8_t *o = v + k * FP_OP;
        uint8_t *d = b + k * 17u;
        for (i = 0; i < 11u; i++)
            d[i] = o[i] & 0x7Fu;
        d[11] = (uint8_t)((o[FP_LC] & 3u) | (o[FP_RC] & 3u) << 2);
        d[12] = (uint8_t)((o[FP_RS] & 7u) | (o[FP_DET] & 15u) << 3);
        d[13] = (uint8_t)((o[FP_AMS] & 3u) | (o[FP_KVS] & 7u) << 2);
        d[14] = o[FP_OL] & 0x7Fu;
        d[15] = (uint8_t)((o[FP_MODE] & 1u) | (o[FP_FC] & 31u) << 1);
        d[16] = o[FP_FF] & 0x7Fu;
    }
    for (i = 0; i < 9u; i++)
        b[102 + i] = v[FP_PR1 + i] & 0x7Fu;
    b[110] &= 31u;
    b[111] = (uint8_t)((v[FP_FB] & 7u) | (v[FP_OKS] & 1u) << 3);
    for (i = 0; i < 4u; i++)
        b[112 + i] = v[FP_LFS + i] & 0x7Fu;
    b[116] = (uint8_t)((v[FP_LKS] & 1u) | (v[FP_LFW] & 7u) << 1 | (v[FP_LPMS] & 7u) << 4);
    b[117] = v[FP_TRNSP] & 0x7Fu;
    for (i = 0; i < 10u; i++)
        b[118 + i] = v[FP_NAME + i] & 0x7Fu;
}
/* ---------------------------------------------------- the track's patch --- */
/* track tr's patch = v (155 bytes, sanitized). Main loop: the ISR takes it at its next block */
static void fm6_set_patch(uint32_t tr, const uint8_t *v)
{
    uint8_t s[FP_SIZE + 1u];
    tr %= 6;
    memcpy(s, v, FP_SIZE);
    fm6_sanitize(s); /* not in place: fm6_sync must never copy an unsanitized byte */
    memcpy(PKV(40)[tr], s, FP_SIZE + 1u);
    __asm__ volatile("" ::: "memory");
    PKV(41)[tr]++;
}
/* SLOT value s < FM6_NFACTORY: that factory patch into track tr; a bank slot: its voice (0 = loaded; 1 = the bank
 * has none there, nothing changed) */
static int fm6_load_slot(uint32_t tr, uint32_t s)
{
    uint8_t v[FP_SIZE + 1u], pk[128u];
    int32_t k = fm6_bank_slot((int32_t)s);
    if (k < 0) {
        s %= 8;
        memcpy(pk, FM6_FACTORY[s], 128u);
    } else if (!fm6_slot_ok((int32_t)s) || !PKV(51) || PKV(51)((uint32_t)k, pk)) {
        return 1;
    }
    fm6_unpack(pk, v);
    fm6_set_patch(tr, v);
    PKV(42)[tr % 6] = (uint8_t)s;
    return 0;
}
/* (0.9.14) the slowest release among the carriers of track t's patch (R4, 0..99): its SLOT's factory patch (P_E7), else
 * the patch it has (OWN, a bank voice). GEN keeps an FM6 part's REL within it (gen.c gen_sound): REL slows R4 by up to
 * 90 steps (fm6_sync), and a GEN pad at REL 78..104 left R4 at 1, a release of minutes: its chords' voices sounded on
 * for good after the notes (and the transport) stopped, at the cost of the heaviest engine */
static uint32_t fm6_rel_r4(const track_t *t)
{
    int32_t s = t->p[P_E7], a = t->p[P_E0];
    uint32_t k, car, r = 99u, tr = (uint32_t)(t - PKV(4)) % 6, f = s >= 0 && s < (int32_t)8;
    const uint8_t *b = f ? FM6_FACTORY[s] : PKV(40)[tr]; /* (packed: 17 bytes an operator, ALG at 110) */
    car = fm6_carriers(a >= 1 && a <= 32 ? (uint32_t)a - 1u : b[f ? 110u : FP_ALG] & 31u);
    for (k = 0; k < 6u; k++)
        if ((car >> k) & 1u && (b[k * (f ? 17u : FP_OP) + 3u] & 0x7Fu) < r)
            r = b[k * (f ? 17u : FP_OP) + 3u] & 0x7Fu;
    return r;
}
/* track tr's patch was just put in as its own (a project, a user preset, the editor, a conversion): an FM6 track's
 * SLOT shows the factory patch it equals unchanged (F n; the SLOT it had first), else OWN; nothing reloads over it
 * (fm6_poll) */
/* (JIANT 0.8.1, "DX7 sounds from the web editor have digital distortion") a voice from outside (the editor, a bank slot
 * B1..B32) plays as its file has it: the macros ALG FB MOD RATIO MEG VMOD DETUNE back to none. A preset's macros are
 * set for its factory patch (HARD BASS: FB +2, MOD +25) and left on a foreign voice they drove its modulators into
 * aliasing noise: 25..40 dB more of it on most DX7 voices (the ROM and Synprez banks through the whole mix) */
static void fm6_neutral(uint32_t tr)
{
    uint32_t k;
    for (k = 0; k < 7u; k++)
        PKV(4)[tr % 6].p[P_E0 + k] = 0;
}
static void fm6_adopt(uint32_t tr)
{
    track_t *t = &PKV(4)[tr % 6];
    int32_t s = t->p[P_E7];
    tr %= 6;
    PKV(44) &= (uint8_t)~(1u << tr);
    if (t->eng_req == 12u) {
        uint8_t v[FP_SIZE + 1u];
        uint32_t k, f = s >= 0 && s < (int32_t)8 ? (uint32_t)s : 0u;
        for (k = 0; k < 8; k++) {
            fm6_unpack(FM6_FACTORY[(f + k) % 8], v);
            if (!memcmp(v, PKV(40)[tr], FP_SIZE))
                break;
        }
        s = k < 8 ? (int32_t)((f + k) % 8) : (int32_t)8;
        t->p[P_E7] = (int16_t)s;
    }
    PKV(42)[tr] = (uint8_t)s;
}
/* a factory sound load put a SLOT value in (a preset, an engine change): its patch (OWN: the patch stays) */
static void fm6_track_loaded(const track_t *t)
{
    uint32_t tr = (uint32_t)(t - PKV(4));
    if (tr < 6 && t->eng_req == 12u) {
        PKV(44) &= (uint8_t)~(1u << tr);
        if (t->p[P_E7] >= 0 && t->p[P_E7] < (int32_t)8)
            fm6_load_slot(tr, (uint32_t)t->p[P_E7]);
        else
            fm6_adopt(tr);
    }
}
/* (0.6.46) INIT SOUND / NEW PROJECT: track t the init voice (OP1 alone at 99, the rates at 99: a plain sine) as its
 * own patch (SLOT OWN), nothing kept aside */
static void fm6_init_voice(track_t *t)
{
    uint8_t v[FP_SIZE + 1u];
    uint32_t tr = (uint32_t)(t - PKV(4));
    if (tr >= 6 || t->eng_req != 12u)
        return;
    fm6_unpack(FM6_INIT, v);
    fm6_set_patch(tr, v);
    PKV(44) &= (uint8_t)~(1u << tr);
    PKV(42)[tr] = 8;
    t->p[P_E7] = 8;
}
/* power-on: every track the init voice (what a project stores for the tracks that never played FM6) */
static void fm6_init(void)
{
    uint8_t v[FP_SIZE + 1u];
    uint32_t tr;
    fm6_unpack(FM6_INIT, v);
    for (tr = 0; tr < 6; tr++) {
        fm6_set_patch(tr, v);
        PKV(42)[tr] = 0xFFu;
    }
}
/* main loop: SLOT turned (a knob, the editor, MIDI, motion) -> that factory patch or bank voice; from OWN the own
 * patch is kept aside (fm6_own), and turning back to OWN brings it back. A bank slot without a voice (the editor, a
 * MIDI CC) is refused: SLOT goes back to what it was, nothing loads */
static void fm6_poll(void)
{
    uint32_t tr, bit;
    for (tr = 0; tr < 6; tr++) {
        int32_t s = PKV(4)[tr].p[P_E7];
        if (PKV(4)[tr].eng_req != 12u || s == PKV(42)[tr])
            continue;
        bit = 1u << tr;
        if (s < 0 || (s >= (int32_t)8 && fm6_bank_slot(s) < 0)) { /* OWN */
            if (PKV(44) & bit) {
                uint8_t v[FP_SIZE + 1u];
                fm6_unpack(PKV(43)[tr], v);
                fm6_set_patch(tr, v);
            }
            PKV(44) &= (uint8_t)~bit;
            PKV(42)[tr] = 8;
            if (s != 8)
                PKV(4)[tr].p[P_E7] = 8;
            continue;
        }
        if (PKV(42)[tr] == 8 && !(PKV(44) & bit) && fm6_slot_ok(s)) {
            fm6_pack(PKV(40)[tr], PKV(43)[tr]);
            PKV(44) |= (uint8_t)bit;
        }
        if (fm6_load_slot(tr, (uint32_t)s)) /* a bank slot without a voice: SLOT back */
            PKV(4)[tr].p[P_E7] = (int16_t)(PKV(42)[tr] <= 8 + 32u ? PKV(42)[tr] : 8);
        else if (fm6_bank_slot(s) >= 0)
            fm6_neutral(tr); /* (a bank voice: as its file has it) */
    }
}
/* -------------------------------------------------------------- macros --- */
/* the patch through E0..E6 (audio ISR; cheap when nothing changed) */
static void fm6_sync(const track_t *t)
{
    uint32_t tr = (uint32_t)(t - PKV(4)), k, j, car, n = 0;
    const int16_t *e = &t->p[P_E0];
    int32_t meg, step;
    if (tr >= 6)
        return;
    if (PKV(45)[tr].ok && PKV(45)[tr].gen == PKV(41)[tr]) {
        for (k = 0; k < 7u && PKV(45)[tr].e[k] == e[k]; k++)
            ;
        for (j = 0; k == 7u && j < 4u && PKV(45)[tr].env[j] == t->p[P_ATK + j]; j++)
            ;
        if (k == 7u && j == 4u)
            return;
    }
    PKV(45)[tr].gen = PKV(41)[tr];
    memcpy(PKV(45)[tr].p, PKV(40)[tr], FP_SIZE);
    for (k = 0; k < 7u; k++)
        PKV(45)[tr].e[k] = e[k];
    for (j = 0; j < 4u; j++)
        PKV(45)[tr].env[j] = t->p[P_ATK + j];
    {
        uint8_t *p = PKV(45)[tr].p;
        uint32_t alg = e[0] >= 1 && e[0] <= 32 ? (uint32_t)e[0] - 1u : p[FP_ALG] & 31u;
        PKV(45)[tr].alg = (uint8_t)alg;
        PKV(45)[tr].fb = (uint8_t)clamp(p[FP_FB] + e[1], 0, 7);
        car = fm6_carriers(alg);
        meg = clamp(e[4], -64, 63) * 40 / 64; /* MEG: rate steps (+ slower) */
        step = clamp(e[6], 0, 127) * (12 * 13981) / 127; /* DTUN: up to 12 cents a step (1 cent = 13981) */
        for (k = 0; k < 6u; k++) {
            uint8_t *op = p + (5u - k) * FP_OP; /* OP1 first: carriers in their order */
            uint32_t ki = 5u - k;
            PKV(45)[tr].dt[ki] = 0;
            if ((car >> ki) & 1u) { /* carriers 0, +1, -1, +2, -2, +3 steps apart */
                static const int8_t SPREAD[6] = {0, 1, -1, 2, -2, 3};
                PKV(45)[tr].dt[ki] = SPREAD[n++] * step;
                /* (0.6.81) the track's ADSR on the carriers, relative to the patch (its defaults 0 0 127 0: the
                 * patch as it is; the ENV page did nothing on FM6): ATK DEC REL slow their stages, SUS sets the
                 * sustain level */
                op[FP_R1] = (uint8_t)clamp(op[FP_R1] - clamp(t->p[P_ATK], 0, 127) * 90 / 127, 1, 99);
                op[FP_R1 + 1u] = (uint8_t)clamp(op[FP_R1 + 1u] - clamp(t->p[P_DEC], 0, 127) * 90 / 127, 1, 99);
                if (t->p[P_SUS] < 127) /* (SUS below the top: the carriers' sustain level, so
                                                         * a decaying patch can be held too) */
                    op[FP_L1 + 2u] = (uint8_t)(t->p[P_SUS] > 0 ? 50 + clamp(t->p[P_SUS], 0, 126) * 49 / 126 : 0); /* (the
                                                         * EG's levels are logarithmic, ~0.75 dB a step: 50..99) */
                op[FP_R1 + 3u] = (uint8_t)clamp(op[FP_R1 + 3u] - clamp(t->p[P_REL], 0, 127) * 90 / 127, 1, 99);
                continue;
            }
            if (!op[FP_MODE])
                op[FP_FC] = (uint8_t)clamp(op[FP_FC] + e[3], 0, 31);
            for (j = 0; j < 4u; j++)
                op[FP_R1 + j] = (uint8_t)clamp(op[FP_R1 + j] - meg, 0, 99);
            op[FP_KVS] = (uint8_t)clamp(op[FP_KVS] + e[5], 0, 7);
        }
        fm6_lfo_reset(&PKV(46)[tr], p);
    }
    PKV(45)[tr].ok = 1;
}
/* --------------------------------------------------------------- voice --- */
static fm6_note_t *fm6_note_of(track_t *t, voice_t *v)
{
    uint32_t i;
    if (t < &PKV(4)[0] || t >= &PKV(4)[6])
        return 0;
    i = (uint32_t)(v - t->v);
    return i < 4 ? &PKV(49)[t - PKV(4)][i] : 0;
}
static void fm6_note_on(track_t *t, voice_t *v)
{
    fm6_note_t *n = fm6_note_of(t, v);
    uint32_t tr = (uint32_t)(t - PKV(4));
    const uint8_t *p;
    if (!n)
        return;
    fm6_sync(t);
    p = PKV(45)[tr].p;
    fm6_note_init(n, p, (int32_t)v->note + p[FP_TRNSP] - 24, v->mvel ? v->mvel : v->vel,
                  (!v->env && !v->env_out) || !n->live); /* from silence: phases and gains from 0 */
    n->trim = 255; /* (its first block: the track's trim at once) */
    fm6_lfo_key(&PKV(46)[tr]);
}
static void fm6_block(track_t *t) /* once a block and part: the macros, the LFO */
{
    uint32_t tr = (uint32_t)(t - PKV(4));
    if (tr >= 6)
        return;
    fm6_sync(t);
    if (PKV(53)[tr] != PKV(41)[tr]) { /* a new patch: its own trim, from none (an edit: kept) */
        PKV(53)[tr] = PKV(41)[tr];
        if (!((PKV(54) >> tr) & 1u))
            PKV(52)[tr] = 0;
        PKV(54) &= (uint8_t)~(1u << tr);
    }
    PKV(47)[tr] = fm6_lfo_sample(&PKV(46)[tr]);
    PKV(48)[tr] = fm6_lfo_delay(&PKV(46)[tr]);
}
/* every carrier has gone silent for good: the voice ends (voice.c, engine_t.done) */
static int fm6_done(track_t *t, voice_t *v)
{
    fm6_note_t *n = fm6_note_of(t, v);
    uint32_t tr = (uint32_t)(t - PKV(4));
    if (!n || !n->live)
        return 1;
    if (!fm6_note_done(n, PKV(45)[tr].p, PKV(45)[tr].alg))
        return 0;
    n->live = 0;
    return 1;
}
static void fm6_render(track_t *t, voice_t *v, int32_t *out, uint32_t len, const vmod_t *m)
{
    fm6_note_t *n = fm6_note_of(t, v);
    uint32_t tr = (uint32_t)(t - PKV(4)), i;
    const uint8_t *p;
    int32_t bus[32], lf, fb, lvl, k, a, da, pk = 0;
    uint32_t tb;
    if (!n || !n->live || len != 32)
        return;
    p = PKV(45)[tr].p;
    if (!v->gate && n->down)
        fm6_note_key(n, p, 0);
    lf = fm6_note_logfreq(m->pitch16 + (p[FP_TRNSP] - 24) * 16, m->fine);
    fb = clamp(PKV(45)[tr].fb + ((m->shape - (64 << 8)) >> 11), 0, 7);
    lvl = clamp(t->p[P_E2], -64, 63) * 24 + clamp(m->cutoff >> 8, -150, 150) * 16 + /* microsteps */
          clamp((m->shape - (64 << 8)) >> 8, -150, 150) * 16; /* (0.6.81) SHAPE: the modulators' depth too (the
                                                         * feedback alone was silent where its operator is quiet) */
    if (!fm6_note_compute(n, p, bus, PKV(47)[tr], PKV(48)[tr], lf, PKV(45)[tr].alg, fb, PKV(45)[tr].dt, lvl << 16))
        return; /* every carrier below the threshold */
    /* the voice's amplitude ramp x VOICE_FS (one carrier at full: VOICE_FS / 2), six voices in unison ~ one */
    k = t->p[P_VOICE] == V_UNISON ? 24000 * 2 / 5 : 24000;
    for (i = 0; i < 32; i++) { /* the block's peak first: its trim from this block on */
        int32_t x = bus[i] - n->dc, ax = x < 0 ? -x : x; /* (as it goes out: past the DC blocker) */
        pk = ax > pk ? ax : pk;
    }
    pk >>= 10; /* (2^26 >> 10 = 2^16: the products fit 32 bits) */
    if ((uint32_t)pk * (256u - PKV(52)[tr]) > (uint32_t)((1 << 26) >> 10) << 8) { /* over: down to there */
        uint32_t g = ((uint32_t)((1 << 26) >> 10) << 8) / (uint32_t)pk; /* the gain that would sit there */
        PKV(52)[tr] = (uint8_t)(256u - (g < 8u ? 8u : g)); /* (-30 dB at most) */
    }
    if (n->trim == 255u) /* (255: never a trim, -30 dB is 248) */
        n->trim = PKV(52)[tr];
    tb = 256u - PKV(52)[tr]; /* the trim from the note's last block to the track's now */
    a = (mulq15(m->amp0, k) * (int32_t)(256u - n->trim)) >> 8;
    da = (((mulq15(m->amp1, k) * (int32_t)tb) >> 8) - a) >> 5;
    n->trim = PKV(52)[tr];
    for (i = 0; i < 32; i++) {
        int32_t x = bus[i] - n->dc;
        n->dc += x >> 10; /* a one-pole high-pass, ~7 Hz: FM puts sidebands at 0 Hz */
        a += da;
        out[i] += (int32_t)(((int64_t)x * a) >> 26);
    }
}
