 /* (JIANT 0.6.3) the SL PITCH page: the step KNOB 2 edits */
static const param_desc_t *page_desc(const page_t *pg, uint32_t slot, int16_t **valp)
{
    uint32_t id = pg->id[slot];
    if (id == 0xFFu) {
        *valp = 0;
        return 0;
    }
    if (id == 0xFCu) { /* (0.7.6) SCL's KNOB 4: the global ALL TR on the track page */
        *valp = &PKV(5).g[G_STRN];
        return &GP[G_STRN];
    }
    if (id == 0xFEu) { /* (0.6.18) not a song global: the device's setting */
        *valp = &PKV(56);
        return &TRKS_DESC;
    }
    if (id == 0xFBu || id == 0xFAu) { /* (0.9.18) the LFO's MODE and PHASE: views of P_LPHASE */
        int32_t ph = (&PKV(4)[PKV(5).sel])->p[P_LPHASE];
        PKV(58) = (int16_t)(ph < 0);
        PKV(59) = (int16_t)(ph < 0 ? PKV(60)[PKV(5).sel % 6] : ph);
        *valp = id == 0xFBu ? &PKV(58) : &PKV(59);
        return id == 0xFBu ? &LFO_MODE_DESC : &LFO_PHASE_DESC;
    }
    if (id == 0xFDu) { /* (0.6.30) the same */
        *valp = &PKV(57);
        return &LOAD_DESC;
    }
    if (pg->scope == SC_STEP || pg->scope == SC_TRK) {
        *valp = 0;
        return 0;
    }
    if (pg->scope == SC_GLOBAL) {
        if (pg->graph == GR_SLPIT && id == G_SLP0) /* the pitch of the step shown */
            id += PKV(63) & 15u;
        *valp = &PKV(5).g[id];
        if (PKV(5).g[G_RTYPE] == 3 && (id == G_RPRE || id == G_RDAMP)) /* (0.6.5) RESO: PITCH, FOLW in their slots */
            return id == G_RPRE ? &RESO_PITCH : &RESO_FOLW;
        if (id == G_RPRE) /* (0.6.12) SHIMMER / CLOUD: AIR; ROOM / SPRING: PRE */
            return PKV(5).g[G_RTYPE] == 2 || PKV(5).g[G_RTYPE] == 4 ? &REV_AIR : &REV_PRE;
        return &GP[id];
    }
    if (pg->graph == GR_MOD) /* SRC DST AMT of the slot shown */
        id += 3u * PKV(61);
    if (pg->graph == GR_MSEQ && id == P_MS0) /* the level of the step shown */
        id += PKV(62) & 15u;
    *valp = &(&PKV(4)[PKV(5).sel])->p[id];
    if (id == P_SLPAT && (&PKV(4)[PKV(5).sel])->p[P_SLDEPTH]) /* (0.6.9) AUTO PAN on the tempo: a division */
        return &AP_BEAT;
    return track_desc((&PKV(4)[PKV(5).sel]), id);
}
