        uint32_t sh = PKV(145) == 2u ? 5u : 6u; /* rounded step stopped at |x - lc| < 32: an offset) */
        int32_t b = PKV(145) == 2u ? spk_bass((*l + *r) >> 1) : 0;
        *l = lowcut1(*l, &PKV(146), &PKV(154)[0], sh);
        *l = lowcut1(*l, &PKV(147), &PKV(154)[1], sh) + b;
        *r = lowcut1(*r, &PKV(148), &PKV(154)[2], sh);
        *r = lowcut1(*r, &PKV(149), &PKV(154)[3], sh) + b;
