 /* the section's punch-in lane (pfx.c), its tracks (as pfx_tgt) */
static void perf_press(uint32_t e, int down)
{
    if (e == PF_TGT && down)
        PKV(182) = (uint8_t)((PKV(182) + 1u) % 3u);
    if (e == PF_CLR)
        PKV(183) = (uint8_t)(down ? 1u : 0u);
    if (e >= PF_N)
        return;
    if (down) {
        PKV(174) |= (1u << (e));
        PKV(179)[e] = ++PKV(180);
    } else {
        PKV(174) &= ~(1u << (e));
    }
    if (PKV(175)) { /* FX LATCH: a press turns it on or off, letting go does nothing */
        if (down)
            PKV(176) ^= (1u << (e));
        return;
    }
    if (down)
        PKV(173) |= (1u << (e));
    else
        PKV(173) &= ~(1u << (e));
}
static void perf_start(void) { PKV(181).ph = 0; PKV(181).sync = 1; PKV(184) = 0; } /* seq_start: a 1/16 starts with the transport */
/* the SLICER's recordings dropped (when the buffer is taken and given back) */
static void perf_drop_slicer(void) { slicer_drop(); }
/* the buffer effect to play: the last pressed of those running */
static uint32_t perf_pick(uint32_t a)
{
    uint32_t e, best = PF_N;
    a &= (0x1Fu | (1u << (PF_SHUF)) | (1u << (PF_FRZ)));
    for (e = 0; e < PF_M1; e++)
        if (((a >> e) & 1u) && (best == PF_N || (uint16_t)(PKV(179)[e] - PKV(179)[best]) < 0x8000u))
            best = e;
    return best;
}
/* (0.9.17) the glitcher whose knobs the FX layer's are: the last pressed of those whose key is down (PF_N: none) */
static uint32_t perf_gfocus(void) { return PKV(168) ? PF_N : perf_pick(PKV(174) & ((1u << (PF_GLT)) | (1u << (PF_TAPE)) | (1u << (PF_SHUF)) | (1u << (PF_FRZ)))); }
static uint32_t perf_gx(uint32_t e) { return e == PF_GLT ? GX_GLT : e == PF_TAPE ? GX_TAPE : e == PF_SHUF ? GX_SHUF : GX_FRZ; }
/* (0.9.14) a slice's place in its 2-bar cycle (and its variation) to 32 random bits */
static uint32_t pf_hash(uint32_t h)
{
    h *= 0x9E3779B1u;
    h = (h ^ (h >> 15)) * 0x2C1B3C6Du;
    return h ^ (h >> 13);
}
static uint32_t semi_q16(int32_t st); /* fx.c: 2^(st / 12), Q16 */
static void perf_glt_step(void);
static void perf_shuf_step(void);
static void perf_frz_grain(void);
static void perf_buf_start(uint32_t e)
{
    uint32_t b = beat_samples();
    if (!PKV(104)) {
        PKV(104) = 1;
        perf_drop_slicer();
    }
    PKV(181).src = (uint8_t)e;
    PKV(181).next = PF_N;
    PKV(181).wr = PKV(181).rp = 0;
    PKV(181).odd = 0;
    PKV(181).xn = 0;
    PKV(181).mode = e == PF_GLT ? BM_GLT : e == PF_TAPE ? BM_TAPE : e == PF_SHUF ? BM_SHUF : e == PF_FRZ ? BM_FRZ : BM_LOOP;
    PKV(181).state = 0;
    PKV(181).len = perf_len(e);
    memset(&PKV(181).u, 0, sizeof PKV(181).u);
    memset(PKV(102)[8192u - 2u], 0, 2u * sizeof PKV(102)[0]); /* (what GLITCH / TAPE read before the start: quiet) */
    if (e == PF_GLT || e == PF_SHUF) { /* its first 1/16: the transport's (this block's split starts the next one) */
        PKV(181).gs = PKV(5).playing && PKV(64) != 0xFFFFFFFFu ? PKV(66) + (PKV(181).split ? 1u : 0u) : 0u;
        if (e == PF_GLT) {
            perf_glt_step();
        } else {
            PKV(181).u.s.r[0].live = 1; /* (live until a chunk moves) */
            perf_shuf_step();
        }
    }
    if (e == PF_TAPE) { /* two frames behind (quiet), at full speed falling to 0 over TIME */
        int32_t c = PKV(170)[GX_TAPE][2];
        uint32_t t = b >> (4u - (uint32_t)clamp(PKV(170)[GX_TAPE][1], 0, 4)), m = 15000u * 600u / (uint32_t)(300 - c);
        PKV(181).u.t.p = ((2u * 8192u) - 4u) << 16; /* (it falls behind by t (1/2 - CURVE / 6): at most TP_LAG) */
        PKV(181).u.t.c = c * 327;
        PKV(181).u.t.dx = (1u << 24) / (t < m ? (t > 64u ? t : 64u) : m);
        PKV(181).u.t.sc = PKV(171);
    }
    if (e == PF_FRZ) { /* the eighth after the press, then the grains */
        PKV(181).u.f.c = b / 2u < (2u * 8192u) - 1024u ? (b / 2u > 4096u ? b / 2u : 4096u) : (2u * 8192u) - 1024u;
        PKV(181).u.f.rnd = 0x2545F491u;
        PKV(181).u.f.sd = 1;
        PKV(181).u.f.v[0].x = PKV(181).u.f.v[1].x = PKV(181).u.f.v[2].x = PKV(181).u.f.v[3].x = 65536u;
    }
}
/* the buffer effect to play becomes e (at a 1/16): a shorter REPEAT of what is
 * recorded switches with a cross-fade, anything else fades the old one out first */
static void perf_buf_select(uint32_t e)
{
    if (e == PKV(181).src && PKV(181).next == PF_N)
        return;
    if (e != PF_N && PKV(181).mode == BM_LOOP && PKV(181).state && e <= PF_R32 && PKV(181).src != PF_N &&
        perf_len(e) <= 2u * PKV(181).wr) {
        PKV(181).xrp = PKV(181).rp;
        PKV(181).xlen = PKV(181).len;
        PKV(181).xn = (1 << 7);
        PKV(181).src = (uint8_t)e;
        PKV(181).next = PF_N;
        PKV(181).len = perf_len(e);
        PKV(181).rp = 0;
        return;
    }
    if (PKV(181).mode == BM_NONE || !PKV(181).w) {
        if (e == PF_N) {
            PKV(181).src = PF_N;
            PKV(181).next = PF_N;
        } else {
            perf_buf_start(e);
        }
        return;
    }
    PKV(181).src = PF_N; /* fade out, then the next one (perf_seg) */
    PKV(181).next = (uint8_t)e;
}
/* each block, after the keys (seq.c) and before the parts: what runs, the 1/16, the sweeps, the mutes.
 * Returns 1 when a stage has something to do */
/* (0.6.19) a track let go from its mute, silent (its voices ended at 0, perf_hush_end): nothing to ramp back, open at
 * once; else mix_part never reached perf_mute again (no signal) and the FX layer stayed busy every block */
static void perf_unhush(void) /* (out of perf_begin: target_budget.py) */
{
    uint32_t k, i, on;
    for (k = 0; k < 6; k++)
        if (!PKV(181).mg[k] && !((PKV(181).act >> (PF_M1 + k)) & 1u)) {
            for (i = on = 0; i < 8; i++)
                on |= PKV(4)[k].v[i].active;
            if (!on)
                PKV(181).mg[k] = 32768;
        }
}
/* (0.9.14) the sweeps (CRUSH, THROW): held, 2 bars from dry to wet; let go, a beat back; their S curve (3 p^2 - 2 p^3) */
static void perf_sweeps(uint32_t n)
{
    uint32_t k, b = beat_samples(), up = (n << 24) / (8u * (b ? b : 1u)), dn = (n << 24) / (b ? b : 1u);
    for (k = 0; k < 2u; k++) {
        uint32_t x = PKV(181).sw[k], p;
        if ((PKV(181).act >> (PF_SCRU + k)) & 1u)
            x = x + up < (1u << 24) ? x + up : 1u << 24;
        else
            x = x > dn ? x - dn : 0u;
        PKV(181).sw[k] = x;
        p = x >> 9; /* (Q15) */
        PKV(181).ss[k] = (int32_t)(((p * p) >> 15) * (3u * 32768u - 2u * p) >> 15);
    }
}
static int perf_begin(uint32_t n)
{
    uint32_t held = PKV(168) ? 0u : (PKV(173) | PKV(176) | PKV(178) | (PKV(166) ? (~(uint32_t)PKV(166) & ((1u << 6) - 1u)) << PF_M1 : 0u)) & perf_avail() & ~(((1u << (PF_RND + 1)) - 1u) & ~((1u << PF_OCTD) - 1u));
    uint32_t q, k, ph0, bnd;
    int32_t lp = -(int32_t)(PKV(169)[3] * 64u / 100u);
    if (!held && !PKV(181).busy) { /* idle: the clock only */
        PKV(181).ph += n;
        PKV(181).sync = 0;
        PKV(177) = 0;
        PKV(94) = 0;
        PKV(133) = (int8_t)lp;
        return 0;
    }
    PKV(181).P = beat_samples() >> 2;
    if (PKV(181).sync) {
        PKV(181).ph = 0;
        PKV(181).sync = 0;
    }
    if (PKV(5).playing && PKV(64) != 0xFFFFFFFFu) /* (JIANT) playing: the transport's 1/16 (seq.c click_tick, through
                                                     * tempo changes and an external clock), so a REPEAT starts on the grid */
        PKV(181).P = div_samples(2);
    ph0 = (PKV(5).playing && PKV(64) != 0xFFFFFFFFu ? PKV(64) : PKV(181).ph) % PKV(181).P; /* the 1/16 in this block (n: none) */
    bnd = ph0 ? (PKV(181).P - ph0 < n ? PKV(181).P - ph0 : n) : 0u;
    PKV(181).ph += n;
    PKV(181).act &= held; /* let go: at once */
    PKV(181).act |= held & (~(0x1Fu | (1u << (PF_SHUF)) | (1u << (PF_FRZ))) | PKV(178)); /* (the lane's: on its own step, already the 1/16's) */
    PKV(181).act0 = PKV(181).act;
    q = held & (0x1Fu | (1u << (PF_SHUF)) | (1u << (PF_FRZ))) & ~PKV(181).act;
    PKV(181).split = n;
    if (q && (!PKV(5).playing || bnd < n)) {
        PKV(181).split = PKV(5).playing ? bnd : 0u;
        PKV(181).act |= q;
    }
    PKV(177) = PKV(181).act;
    perf_sweeps(n);
    PKV(133) = (int8_t)lp; /* (the FILTER macro's low-pass; 0.9.17: no sweep over it) */
    PKV(181).mute = 0;
    perf_unhush();
    for (k = 0; k < 6; k++)
        if (((held >> (PF_M1 + k)) & 1u) || PKV(181).mg[k] != 32768)
            PKV(181).mute |= (uint8_t)(1u << k);
    PKV(94) = (uint8_t)((PKV(181).act >> PF_M1) & ((1u << 6) - 1u)); /* (0.6.15) muted: no new notes (voice.c) */
    PKV(181).busy = 1;
    return 1;
}
/* a track muted by its black key: its signal ramps to 0 and back (fx.c mix_part, after the SLICER) */
static void perf_hush_end(uint32_t k) /* (out of perf_mute's loop: target_budget.py) */
{
    uint32_t i;
    for (i = 0; i < 8; i++) {
        voice_t *v = &PKV(4)[k].v[i];
        v->active = v->gate = 0;
        v->stage = 0;
        v->env = v->env_out = 0;
    }
}
static void perf_mute(uint32_t k, int32_t *b, uint32_t n)
{
    uint32_t i;
    int32_t g = PKV(181).mg[k], t = (PKV(181).act >> (PF_M1 + k)) & 1u ? 0 : 32768;
    for (i = 0; i < n; i++) {
        g += clamp(t - g, -(32768 / (1 << 7)), (32768 / (1 << 7)));
        b[i] = mulq16(b[i], (uint32_t)g << 1);
    }
    PKV(181).mg[k] = g;
    if (!g && !t) /* (0.6.15) silent: its voices end, the track costs nothing
                                                         * while muted (a MIDI mute: no new notes, trk_hush) */
        perf_hush_end(k);
}
/* before the buses: THROW (its sweep) adds the dry mix (and the SLICER's bus, bl / br) to the delay and reverb sends */
static void perf_pre(const int32_t *ml, const int32_t *mr, const int32_t *bl, const int32_t *br,
                                               int32_t *sd, int32_t *sr, uint32_t n)
{
    uint32_t i;
    int32_t m = PKV(181).ss[1];
    for (i = 0; i < n; i++) {
        PKV(181).td += clamp(m - PKV(181).td, -(32768 / (1 << 7)), (32768 / (1 << 7)));
        if (PKV(181).td) {
            int32_t x = mulq16((ml[i] + mr[i] + bl[i] + br[i]) >> 1, (uint32_t)PKV(181).td << 1);
            sd[i] += x;
            sr[i] += x;
        }
    }
}
/* x towards y by w (Q15, 32768 = y) */
static inline int32_t pf_mix(int32_t x, int32_t y, int32_t w)
{
    return w == 32768 ? y : x + mulq16(y - x, (uint32_t)w << 1);
}
/* the loop: frame f of it, both channels (Q15) */
static inline void pb_put(uint32_t f, int32_t l, int32_t r)
{
    int16_t *p = &PKV(102)[0][0] + 2u * (f & (8192u - 1u));
    p[0] = (int16_t)clamp(l, -32768, 32767);
    p[1] = (int16_t)clamp(r, -32768, 32767);
}
/* sample s of the frames recorded from 0 (n of them): between two frames on an odd one */
static inline void pb_at(uint32_t s, uint32_t n, int32_t *l, int32_t *r)
{
    uint32_t f = s >> 1 < n ? s >> 1 : n - 1u; /* (an odd loop's last sample: the frame before) */
    const int16_t *p = &PKV(102)[0][0] + 2u * (f & (8192u - 1u));
    const int16_t *q; /* a frame is the mean of samples 2f, 2f + 1: sample s */
    if (s & 1u) /* lies a quarter frame from it, towards f + 1 or f - 1 */
        q = f + 1u < n ? p + 2 : p;
    else
        q = f ? p - 2 : p;
    *l = (3 * p[0] + q[0]) >> 1;
    *r = (3 * p[1] + q[1]) >> 1;
}
/* (0.9.17) the loop as a ring (GLITCH, TAPE, FREEZE: frames recorded on and on) at the place s (Q16 of a 44.1 kHz
 * sample), between its two frames (linear): any speed, backwards too */
static void pb_ring_f(uint32_t s, int32_t *l, int32_t *r)
{
    uint32_t f = s >> 17;
    int32_t fr = (int32_t)((s >> 2) & 0x7FFFu);
    const int16_t *p = &PKV(102)[f & (8192u - 1u)][0], *q = &PKV(102)[(f + 1u) & (8192u - 1u)][0];
    *l = 2 * (p[0] + (((q[0] - p[0]) * fr) >> 15));
    *r = 2 * (p[1] + (((q[1] - p[1]) * fr) >> 15));
}
/* REPEAT at sample rp of a loop of len, windowed at both ends */
static inline void pb_loop(uint32_t rp, uint32_t len, uint32_t n, int32_t *l, int32_t *r)
{
    uint32_t e = len - 1u - rp;
    pb_at(rp, n, l, r);
    if (rp < e)
        e = rp;
    if (e < (uint32_t)(1 << 7)) {
        *l = (*l * (int32_t)e) >> 7;
        *r = (*r * (int32_t)e) >> 7;
    }
}
/* record the pair into frame f (the mean, >> 1: headroom) */
static inline uint32_t pb_rec(uint32_t f, int32_t l, int32_t r)
{
    if (!PKV(181).odd) {
        PKV(181).hl = l;
        PKV(181).hr = r;
        PKV(181).odd = 1;
        return f;
    }
    PKV(181).odd = 0;
    pb_put(f, (PKV(181).hl + l) >> 2, (PKV(181).hr + r) >> 2);
    return f + 1u;
}
/* ------------------------------------------------------------------ GLITCH --- */
/* (0.9.17) a glitched 1/16's action, by 4 bits of its hash: repeats most, then the rest */
static const uint8_t GA_OF[16] = {GA_RPT, GA_RPT, GA_RPT, GA_RPT, GA_RPT, GA_RPT, GA_REV, GA_REV, GA_UP, GA_DN,
                                  GA_GATE, GA_GATE, GA_SKIP, GA_SKIP, GA_CRU, GA_CRU};
/* a segment's start: where it reads (Q16) and how fast (a REPEAT's k-th: PITCH k times; SKIP: a place in the 1/16,
 * two segments at each) */
static void perf_glt_seg(void)
{
    uint32_t a = PKV(181).u.g.a, L = PKV(181).u.g.l, g0 = PKV(181).u.g.g0, s = g0 - L;
    PKV(181).u.g.rate = 65536;
    if (a == GA_RPT) {
        PKV(181).u.g.rate = (int32_t)semi_q16(clamp((int32_t)(PKV(181).u.g.k < 24u ? PKV(181).u.g.k : 24u) * PKV(170)[GX_GLT][1], -24, 24));
    } else if (a == GA_REV) {
        s = g0 - 1u;
        PKV(181).u.g.rate = -65536;
    } else if (a == GA_UP) {
        s = g0 - 2u * L;
        PKV(181).u.g.rate = 131072;
    } else if (a == GA_DN) {
        PKV(181).u.g.rate = 32768;
    } else if (a == GA_SKIP) {
        s = g0 - PKV(181).u.g.sp + pf_hash(PKV(181).gs * 64u + (PKV(181).u.g.k >> 1)) % (PKV(181).u.g.sp - L + 1u);
    }
    PKV(181).u.g.src = s << 16;
}
/* (0.9.14) GLITCH: the next 1/16's slice, by the hash of its place in two bars (0.9.17: and VARI; DENS of them glitched,
 * the beats DENS squared: at 50 %, one beat in four) */
static void perf_glt_step(void)
{
    uint32_t h = pf_hash((PKV(181).gs & 31u) + 0x51u + ((uint32_t)(PKV(170)[GX_GLT][3] - 1) << 5)), s16 = PKV(181).P ? PKV(181).P : 1u,
             sp = s16 < 7680u ? s16 : 7680u, d = (uint32_t)PKV(170)[GX_GLT][0], z = (uint32_t)PKV(170)[GX_GLT][2],
             j = (h >> 12) % 3u, a, L;
    a = ((h >> 24) * 100u >> 8) < (PKV(181).gs & 3u ? d : d * d / 100u) ? GA_OF[(h >> 8) & 15u] : GA_PASS;
    PKV(181).u.g.g0 = 2u * PKV(181).wr + PKV(181).odd; /* (the loop's sample now) */
    if ((s16 + sp > (2u * 8192u) - 512u || PKV(181).u.g.g0 < sp) && a != GA_GATE && a != GA_CRU)
        a = GA_PASS; /* (too slow: what it would read is gone; or not recorded yet) */
    L = a == GA_RPT ? sp >> (z + j) : a == GA_GATE ? (s16 / 2u) >> (z / 2u + j % 2u) : a == GA_SKIP ? sp >> (3u + z / 2u + j % 2u)
      : a == GA_UP ? sp / 2u : a == GA_CRU ? s16 : sp;
    PKV(181).u.g.a = (uint8_t)a;
    PKV(181).u.g.l = L < 2u * (1 << 7) ? 2u * (1 << 7) : L;
    PKV(181).u.g.sp = sp;
    PKV(181).u.g.h = (uint8_t)(1u + (h >> 14) % 6u); /* CRUSH: a sample held 1 .. 6, 6 .. 9 bits off (of Q15) */
    PKV(181).u.g.sh = (uint8_t)(6u + j + (h >> 20) % 2u);
    PKV(181).u.g.n = 255u;
    PKV(181).u.g.u = PKV(181).u.g.k = PKV(181).gph = 0;
    perf_glt_seg();
}
/* GLITCH on one sample: 1 = it plays (pf.yl yr), 0 = live */
static int perf_glt(int32_t l, int32_t r)
{
    uint32_t u = PKV(181).u.g.u, L = PKV(181).u.g.l, a = PKV(181).u.g.a, e = L - 1u - u < u ? L - 1u - u : u, g = 32768u;
    PKV(181).wr = pb_rec(PKV(181).wr, l, r);
    if (a != GA_PASS) {
        if (a == GA_SKIP) { /* (each segment windowed; SKIP's edges 0.7 ms: a tick, shaped) */
            if (e < (1 << 7) / 4u)
                g = e << (17 - 7);
        } else if (e < (uint32_t)(1 << 7)) {
            g = e << (15 - 7);
        }
        if (a == GA_GATE) {
            g = PKV(181).u.g.k & 1u ? 0u : g;
            PKV(181).yl = mulq16(l, g << 1);
            PKV(181).yr = mulq16(r, g << 1);
        } else if (a == GA_CRU) { /* (live, crushed; windowed as the others) */
            if (++PKV(181).u.g.n >= PKV(181).u.g.h) {
                int32_t b = 1 << (PKV(181).u.g.sh - 1u);
                PKV(181).u.g.n = 0;
                PKV(181).u.g.cl = ((l + b) >> PKV(181).u.g.sh) << PKV(181).u.g.sh; /* (to the nearest: silence stays 0, no DC) */
                PKV(181).u.g.cr = ((r + b) >> PKV(181).u.g.sh) << PKV(181).u.g.sh;
            }
            PKV(181).yl = mulq16(PKV(181).u.g.cl, g << 1);
            PKV(181).yr = mulq16(PKV(181).u.g.cr, g << 1);
        } else {
            pb_ring_f(PKV(181).u.g.src + (uint32_t)((int32_t)u * (PKV(181).u.g.rate >> 2)) * 4u, &PKV(181).yl, &PKV(181).yr);
            PKV(181).yl = mulq16(PKV(181).yl, g << 1);
            PKV(181).yr = mulq16(PKV(181).yr, g << 1);
        }
    }
    if (++PKV(181).u.g.u >= L) {
        PKV(181).u.g.u = 0;
        PKV(181).u.g.k++;
        perf_glt_seg();
    }
    if (++PKV(181).gph >= PKV(181).P) {
        PKV(181).gs++;
        perf_glt_step();
    }
    return a != GA_PASS;
}
/* --------------------------------------------------------------- TAPE STOP --- */
/* TAPE on one sample: stopping (the speed (1 - x)(1 + CURVE x), x 0 .. 1 over TIME, the level 4x the speed up to 1),
 * then stopped: the scratch (KNOB 1 the hand, perf_scratch; the platter two one-poles of 256 samples behind it) */
static int perf_tape(int32_t l, int32_t r)
{
    uint32_t g;
    if (!PKV(181).state) {
        uint32_t xq = PKV(181).u.t.x >> 9, v = (32768u - xq) * (uint32_t)(32768 + ((PKV(181).u.t.c * (int32_t)xq) >> 15)) >> 15;
        PKV(181).wr = pb_rec(PKV(181).wr, l, r);
        g = v < 8192u ? v << 2 : 32768u;
        pb_ring_f(PKV(181).u.t.p, &PKV(181).yl, &PKV(181).yr);
        PKV(181).u.t.p += v << 1;
        if ((PKV(181).u.t.x += PKV(181).u.t.dx) >= 1u << 24) { /* stopped: the loop kept (no more recording), the hand on it */
            PKV(181).state = 1;
            PKV(181).u.t.q = PKV(181).u.t.p1 = PKV(181).u.t.p;
        }
    } else {
        uint32_t p0 = PKV(181).u.t.p;
        int32_t d;
        PKV(181).u.t.p1 += (uint32_t)((int32_t)(PKV(181).u.t.q - PKV(181).u.t.p1) >> 8);
        PKV(181).u.t.p += (uint32_t)((int32_t)(PKV(181).u.t.p1 - PKV(181).u.t.p) >> 8);
        d = (int32_t)(PKV(181).u.t.p - p0);
        d = d < 0 ? -d : d; /* (its speed, Q16: the level up to a quarter of it; below 1/64 none) */
        PKV(181).u.t.gn += ((d >= 16384 ? 32768 : d > 1024 ? (d - 1024) << 1 : 0) - PKV(181).u.t.gn) >> 5;
        g = (uint32_t)PKV(181).u.t.gn;
        pb_ring_f(PKV(181).u.t.p, &PKV(181).yl, &PKV(181).yr);
    }
    PKV(181).yl = mulq16(PKV(181).yl, g << 1);
    PKV(181).yr = mulq16(PKV(181).yr, g << 1);
    return 1;
}
/* (0.9.17) each block, stopped: KNOB 1's detents since the last (perf_scr) move the hand 1/48 beat each, within
 * what the loop holds */
static void perf_scratch(void)
{
    uint32_t b = beat_samples() / 48u;
    int32_t d = clamp((int32_t)(PKV(171) - PKV(181).u.t.sc), -64, 64), r0, r1;
    r0 = (int32_t)(((PKV(181).u.t.q >> 16) - 2u * PKV(181).wr) & ((2u * 8192u) - 1u)) - (int32_t)(2u * 8192u); /* (behind the last written) */
    PKV(181).u.t.sc = PKV(171);
    r1 = clamp(r0 + d * (int32_t)(b < 512u ? b : 512u), -(int32_t)((2u * 8192u) - 1024u), -4);
    PKV(181).u.t.q += (uint32_t)(r1 - r0) << 16; /* (on the platter's own lap of the ring) */
}
/* ----------------------------------------------------------------- FREEZE --- */
/* (0.9.17) a new grain (into the voice done, or the oldest): SIZE long at PITCH (SPRAY: some an octave either way, a
 * fifth up, a fourth down), from the scan (SPRAY scatters around it), within the capture; the scan on by 1/8 of the
 * time between grains, back and forth; DENS: 1 .. 3 at once (x100: ov), the level so they sum to about 1 */
static const int8_t FZ_JIT[4] = {12, -12, 7, -5};
static uint32_t frz_ov(void) { return 100u + 2u * (uint32_t)PKV(170)[GX_FRZ][0]; }
static void perf_frz_grain(void)
{
    grain_t *v = &PKV(181).u.f.v[0];
    uint32_t i, r = PKV(181).u.f.rnd = PKV(181).u.f.rnd * 1664525u + 1013904223u, ov = frz_ov(),
             sp = (uint32_t)PKV(170)[GX_FRZ][2], len = beat_samples() >> (5u - (uint32_t)PKV(170)[GX_FRZ][3]), span, room, j;
    int32_t n = PKV(170)[GX_FRZ][1], rate;
    for (i = 1; i < 4u; i++)
        if (PKV(181).u.f.v[i].x > v->x)
            v = &PKV(181).u.f.v[i];
    if (((r >> 24) * 100u >> 8) < sp / 2u)
        n += FZ_JIT[(r >> 22) & 3u];
    rate = (int32_t)semi_q16(n);
    if (len < 256u)
        len = 256u;
    PKV(181).u.f.iv = len * 100u / ov;
    PKV(181).u.f.gain = ov > 150u ? (int32_t)(4915200u / ov) : 32768; /* (1.5 / the overlap: their windows' mean is 2/3) */
    if ((len >> 4) * ((uint32_t)rate >> 12) + 64u > PKV(181).u.f.c) /* (what it reads: within the capture) */
        len = ((PKV(181).u.f.c - 64u) << 4) / ((uint32_t)rate >> 12);
    v->dx = 65536u / len;
    len = 65535u / v->dx + 1u; /* (as the window counts it) */
    span = (len >> 4) * ((uint32_t)rate >> 12) + 2u;
    room = span + 48u < PKV(181).u.f.c ? PKV(181).u.f.c - span - 48u : 0u;
    j = room * sp / 100u;
    if (PKV(181).u.f.scan > room)
        PKV(181).u.f.scan = room;
    i = PKV(181).u.f.scan + (((r >> 6) & 0xFFFFu) * j >> 16);
    i = i > j / 2u ? i - j / 2u : 0u;
    v->pos = (16u + (i < room ? i : room)) << 16;
    v->rate = (uint32_t)rate;
    v->x = 0;
    j = PKV(181).u.f.iv / 8u + 1u; /* (the scan: 1/8 of the speed, back and forth) */
    if (PKV(181).u.f.sd > 0)
        PKV(181).u.f.scan += j;
    else
        PKV(181).u.f.scan = PKV(181).u.f.scan > j ? PKV(181).u.f.scan - j : 0u;
    if (PKV(181).u.f.scan >= room || !PKV(181).u.f.scan)
        PKV(181).u.f.sd = PKV(181).u.f.scan ? -1 : 1;
}
/* the grains' sum at the next even sample (S(t + 1), into nl nr), each on by two samples: at 22.05 kHz, the loop's rate */
static void perf_frz_eval(void)
{
    uint32_t i;
    int32_t al = 0, ar = 0;
    if ((PKV(181).u.f.fs += 2u) >= PKV(181).u.f.iv) {
        PKV(181).u.f.fs = 0;
        perf_frz_grain();
    }
    for (i = 0; i < 4u; i++) {
        grain_t *v = &PKV(181).u.f.v[i];
        if (v->x < 65536u) {
            int32_t gl, gr, w = (int32_t)((v->x * (65536u - v->x)) >> 15);
            pb_ring_f(v->pos, &gl, &gr);
            al += (gl * w) >> 15;
            ar += (gr * w) >> 15;
            v->pos += 2u * v->rate;
            v->x += 2u * v->dx;
        }
    }
    PKV(181).u.f.nl = mulq16(al, (uint32_t)PKV(181).u.f.gain << 1);
    PKV(181).u.f.nr = mulq16(ar, (uint32_t)PKV(181).u.f.gain << 1);
}
/* FREEZE on one sample: recording the capture (live), then the grains: their sum on the even samples, the mean of the
 * two around it on the odd ones (half the work) */
static int perf_frz(int32_t l, int32_t r)
{
    if (!PKV(181).state) {
        uint32_t i, ov;
        PKV(181).wr = pb_rec(PKV(181).wr, l, r);
        if (2u * PKV(181).wr < PKV(181).u.f.c)
            return 0;
        ov = frz_ov() / 100u;
        PKV(181).state = 1; /* frozen: DENS grains at once, staggered (v[0] .. in turn) */
        for (i = 0; i < ov; i++)
            perf_frz_grain();
        for (i = 0; i < ov; i++)
            PKV(181).u.f.v[i].x = i * (6553600u / frz_ov());
        PKV(181).u.f.fs = 0;
        PKV(181).u.f.ph = 1;
        perf_frz_eval();
    }
    if ((PKV(181).u.f.ph ^= 1u) != 0u) { /* (odd: S(t + 1), and the mean) */
        int32_t pl = PKV(181).u.f.nl, pr = PKV(181).u.f.nr;
        perf_frz_eval();
        PKV(181).yl = (pl + PKV(181).u.f.nl) >> 1;
        PKV(181).yr = (pr + PKV(181).u.f.nr) >> 1;
    } else {
        PKV(181).yl = PKV(181).u.f.nl;
        PKV(181).yr = PKV(181).u.f.nr;
    }
    return 1;
}
/* ---------------------------------------------------------------- SHUFFLE --- */
/* (0.9.17) ADPCM, 4 bits, IMA's way (its index moves, its codes) with its steps 2^(1/8) apart (IMA's: 1.1), 8 .. 29696:
 * from 8 numbers, not 89 */
static const uint8_t AD_M[8] = {16, 17, 19, 21, 23, 25, 27, 29};
static const int8_t AD_IDX[8] = {-1, -1, -1, -1, 2, 4, 6, 8};
static int32_t ad_stp(uint32_t ix) { return (int32_t)((uint32_t)AD_M[ix & 7u] << (ix >> 3)) >> 1; }
/* the value after code c from p (the coder and the reader alike), the step index on; (unlike IMA) codes 0 and 8 move
 * nothing, so silence stays 0 (else +-1 forever: the master would never rest, fx.c mix_hush) */
static int32_t ad_next(uint32_t c, int32_t p, uint8_t *ix)
{
    int32_t s = ad_stp(*ix), d = c & 7u ? s >> 3 : 0;
    if (c & 4u) d += s;
    if (c & 2u) d += s >> 1;
    if (c & 1u) d += s >> 2;
    *ix = (uint8_t)clamp((int32_t)*ix + AD_IDX[c & 7u], 0, 95);
    return clamp(c & 8u ? p - d : p + d, -32768, 32767);
}
/* the coder: x (16 bits) into the ring's next nibble */
static void ad_put(int32_t x)
{
    uint32_t w = PKV(181).u.s.ew, c = 0;
    int32_t d = x - PKV(181).u.s.ep, s = ad_stp(PKV(181).u.s.ei);
    uint8_t *b = (uint8_t *)PKV(102) + (w >> 1);
    if (d < 0) {
        c = 8u;
        d = -d;
    }
    if (d >= s) { c |= 4u; d -= s; }
    if (d >= s >> 1) { c |= 2u; d -= s >> 1; }
    if (d >= s >> 2) c |= 1u;
    PKV(181).u.s.ep = ad_next(c, PKV(181).u.s.ep, &PKV(181).u.s.ei);
    *b = (uint8_t)(w & 1u ? (*b & 0x0Fu) | c << 4 : (*b & 0xF0u) | c);
    PKV(181).u.s.ew = w + 1u < (2u * (sizeof PKV(102) - 256u)) ? w + 1u : 0u;
}
/* a reader's sample (the level: x 2), then on by its rate */
static int32_t shr_out(shr_t *q)
{
    int32_t y = q->a + (((q->b - q->a) * (int32_t)(q->fr >> 1)) >> 15);
    if ((q->fr += q->rate) >= 65536u) {
        uint32_t w = q->pos;
        q->fr -= 65536u;
        q->a = q->b;
        q->b = (int16_t)ad_next((uint32_t)((const uint8_t *)PKV(102))[w >> 1] >> (w & 1u ? 4 : 0) & 15u, q->b, &q->idx);
        q->pos = (uint16_t)(w + 1u < (2u * (sizeof PKV(102) - 256u)) ? w + 1u : 0u);
    }
    return 2 * y;
}
/* the reader from the start of the 1/16 noted in slot j (j > 31: live), the one before fading out */
static void perf_shuf_go(uint32_t j, uint32_t rate)
{
    shr_t *c = &PKV(181).u.s.r[0];
    const int16_t *t = (&PKV(102)[8192u - 64u][0]) + 3u * (j & 31u);
    if (j > 31u && c->live)
        return;
    PKV(181).u.s.r[1] = *c;
    PKV(181).u.s.xn = (1 << 7);
    c->live = j > 31u;
    c->pos = (uint16_t)t[0];
    c->a = c->b = t[1];
    c->idx = (uint8_t)t[2];
    c->fr = 0;
    c->rate = rate;
}
/* each 1/16: the coder noted (its slot); a chunk's start: live, or one of the last bar's (the same place in the beat
 * half the time), at its speed (SPEED: half, double, its first half twice) */
static void perf_shuf_step(void)
{
    uint32_t gs = PKV(181).gs, ch = 4u >> PKV(170)[GX_SHUF][1], s16 = PKV(181).P / 2u ? PKV(181).P / 2u : 1u, A = (uint32_t)PKV(170)[GX_SHUF][0],
             h, thr, dm, d, k;
    int16_t *t = (&PKV(102)[8192u - 64u][0]) + 3u * (gs & 31u);
    t[0] = (int16_t)PKV(181).u.s.ew;
    t[1] = (int16_t)PKV(181).u.s.ep;
    t[2] = (int16_t)PKV(181).u.s.ei;
    PKV(181).u.s.nrec++;
    PKV(181).gph = 0;
    if (gs % ch)
        return;
    PKV(181).u.s.cu = 0;
    h = pf_hash((gs & 31u) + 0x3C7u + ((uint32_t)(PKV(170)[GX_SHUF][3] - 1) << 5));
    thr = !(gs & 15u) ? A * A / 100u * A / 100u : !(gs & 3u) ? A * A / 100u : A;
    dm = ((2u * (sizeof PKV(102) - 256u)) - 2048u) / s16; /* (how far back it may read: the bar, what the ring holds) */
    dm = dm > ch + 16u ? 16u : dm > ch ? dm - ch : 0u;
    dm = dm < PKV(181).u.s.nrec - 1u ? dm : PKV(181).u.s.nrec - 1u;
    PKV(181).u.s.kind = SK_NORM;
    if (((h >> 24) * 100u >> 8) >= thr || dm < ch) {
        perf_shuf_go(32u, 0);
        return;
    }
    d = ch < 4u && dm >= 4u && (h & 0x100u) ? 4u * (1u + (h >> 9) % (dm / 4u)) : ch * (1u + (h >> 9) % (dm / ch));
    k = (((h >> 16) & 0xFFu) * 100u >> 8) < (uint32_t)PKV(170)[GX_SHUF][2] ? 1u + (h >> 13) % 3u : SK_NORM;
    PKV(181).u.s.kind = (uint8_t)k;
    PKV(181).u.s.j0 = (uint8_t)((gs - d) & 31u);
    PKV(181).u.s.mid = ch * PKV(181).P / 2u;
    perf_shuf_go(PKV(181).u.s.j0, k == SK_HALF ? 16384u : k == SK_DBL ? 65536u : 32768u);
}
/* SHUFFLE on one sample: the pair coded (mono, 22.05 kHz), the reader (or live), the one before fading out */
static int perf_shuf(int32_t l, int32_t r)
{
    shr_t *c = &PKV(181).u.s.r[0];
    if (PKV(181).odd) {
        ad_put(clamp((PKV(181).hl + l + r) >> 3, -32768, 32767));
        PKV(181).odd = 0;
    } else {
        PKV(181).hl = l + r;
        PKV(181).odd = 1;
    }
    if (c->live) {
        PKV(181).yl = l;
        PKV(181).yr = r;
    } else {
        PKV(181).yl = PKV(181).yr = shr_out(c);
    }
    if (PKV(181).u.s.xn) {
        shr_t *o = &PKV(181).u.s.r[1];
        int32_t g = (int32_t)PKV(181).u.s.xn--, ol = l, orr = r;
        if (!o->live)
            ol = orr = shr_out(o);
        PKV(181).yl += ((ol - PKV(181).yl) * g) >> 7;
        PKV(181).yr += ((orr - PKV(181).yr) * g) >> 7;
    }
    if (++PKV(181).u.s.cu == PKV(181).u.s.mid && PKV(181).u.s.kind >= SK_DBL) /* (DOUBLE, STUTTER: again from the chunk's start) */
        perf_shuf_go(PKV(181).u.s.j0, c->rate);
    if (++PKV(181).gph >= PKV(181).P) {
        PKV(181).gs++;
        perf_shuf_step();
    }
    return 1;
}
/* the glitcher on one sample (BM_GLT ..): 1 = it plays (pf.yl yr), 0 = live. (A table: each stays out of perf_buf on
 * any compiler, as on the target, where they are noinline) */
static int (*const PERF_RING[4])(int32_t, int32_t) = {perf_glt, perf_tape, perf_shuf, perf_frz};
/* the buffer effect faded out: the next one, or the buffer back. Once per effect, out of the per-sample loop
 * (noinline: its calls stay out of perf_block's loop code) */
static void perf_buf_done(void)
{
    if (PKV(181).next != PF_N) {
        perf_buf_start(PKV(181).next);
    } else {
        PKV(181).mode = BM_NONE;
        if (PKV(104)) {
            PKV(104) = 0;
            perf_drop_slicer();
        }
    }
}
/* the buffer effect on one sample: the share pf.w of what it plays, the rest live */
static void perf_buf(int32_t *pl, int32_t *pr) /* (0.9.14: out of perf_block's loop) */
{
    int32_t l = *pl, r = *pr, yl = 0, yr = 0, on = 0;
    if (PKV(181).mode == BM_LOOP) {
        if (!PKV(181).state) {
            PKV(181).wr = pb_rec(PKV(181).wr, l, r);
            if (++PKV(181).rp >= PKV(181).len) { /* (rp: samples recorded) */
                PKV(181).state = 1;
                PKV(181).rp = 0;
            }
        } else {
            pb_loop(PKV(181).rp, PKV(181).len, PKV(181).wr, &yl, &yr);
            if (PKV(181).xn) { /* the loop it switched from, fading out */
                int32_t ol, orr, g = (int32_t)PKV(181).xn;
                pb_loop(PKV(181).xrp, PKV(181).xlen, PKV(181).wr, &ol, &orr);
                yl += (ol * g) >> 7;
                yr += (orr * g) >> 7;
                PKV(181).xn--;
                if (++PKV(181).xrp >= PKV(181).xlen)
                    PKV(181).xrp = 0;
            }
            if (++PKV(181).rp >= PKV(181).len)
                PKV(181).rp = 0;
            on = 1;
        }
    } else {
        if ((on = PERF_RING[(PKV(181).mode - BM_GLT) & 3u](l, r)) != 0) { /* (0.9.14) GLITCH, TAPE; (0.9.17) SHUFFLE, FREEZE */
            yl = PKV(181).yl;
            yr = PKV(181).yr;
        }
    }
    PKV(181).tw = on && PKV(181).src != PF_N ? 32768 : 0;
    PKV(181).w += clamp(PKV(181).tw - PKV(181).w, -(32768 / (1 << 7)), (32768 / (1 << 7)));
    if (PKV(181).w) {
        *pl = pf_mix(l, yl, PKV(181).w);
        *pr = pf_mix(r, yr, PKV(181).w);
    } else if (PKV(181).src == PF_N) { /* faded out: the next one, or the buffer back */
        perf_buf_done();
    }
}
static void perf_switch(uint32_t a) { perf_buf_select(perf_pick(a)); }
/* after the master level: the buffer effect, CRUSH on l / r (stereo, Q15) */
static void perf_block(int32_t *bl, int32_t *br, uint32_t n)
{
    uint32_t i, a = PKV(181).act0, sh, hold;
    int32_t ct = PKV(181).ss[0];
    sh = 4u + (uint32_t)(ct * 7) / 32768u;
    hold = sh - 3u;
    if (PKV(181).split)
        perf_switch(a);
    if (PKV(181).mode == BM_TAPE && PKV(181).state) /* (0.9.17) stopped: the hand (KNOB 1) */
        perf_scratch();
    for (i = 0; i < n; i++) {
        int32_t l = bl[i], r = br[i];
        if (i == PKV(181).split) {
            a = PKV(181).act;
            perf_switch(a);
        }
        if (PKV(181).mode != BM_NONE)
            perf_buf(&l, &r);
        { /* CRUSH: fewer bits, a held sample (its sweep: both, and its mix) */
            PKV(181).cw += clamp(ct - PKV(181).cw, -(32768 / (1 << 7)), (32768 / (1 << 7)));
            if (PKV(181).cw) {
                if (++PKV(181).cn >= hold) {
                    PKV(181).cn = 0;
                    PKV(181).chl = ((l >> sh) << sh) + (1 << (sh - 1u));
                    PKV(181).chr = ((r >> sh) << sh) + (1 << (sh - 1u));
                }
                l = pf_mix(l, PKV(181).chl, PKV(181).cw);
                r = pf_mix(r, PKV(181).chr, PKV(181).cw);
            }
        }
        bl[i] = l;
        br[i] = r;
    }
    PKV(181).busy = PKV(181).act || PKV(181).mode != BM_NONE || PKV(181).w || PKV(181).cw || PKV(181).td || PKV(181).mute || PKV(181).sw[0] || PKV(181).sw[1];
}
static void seq_note_on(track_t *t, uint32_t note, uint32_t vel); /* (0.6.72: seq.c, a note MIDI OUT ALL sends) */
static void seq_note_off(track_t *t, uint32_t note);
