/* the notes a repeat sounds end */
static void pfx_hush(track_t *t)
{
    uint32_t i;
    for (i = 0; i < t->pfx_snn; i++)
        seq_note_off(t, t->pfx_sn[i]);
    t->pfx_snn = 0;
}
/* a repeat: the notes again (STUTTER), or the next of them (ARP) */
static void pfx_fire(track_t *t, int arp)
{
    uint32_t i, n = t->pfx_lnn;
    if (!n && !(arp && t->engine == 10u)) /* (a drum fill needs no notes struck) */
        return;
    if (!n) { /* (0.6.28) .. but a kit with steps: a cleared DRUM track stays
                                                         * silent (the lane's ARP made random fills on it) */
        for (i = 0; i < 64 && !(t->step[i].time == ST_NOTE && (t->step[i].n || t->step[i].hit)); i++) {}
        if (i == 64) return;
    }
    pfx_hush(t);
    PKV(187) = 1;
    t->pfx_rpit = 0;
    if (arp && t->engine == 10u) { /* (JIANT 0.4) a fill: each press its own (pfx_seed runs on) */
        static const uint8_t FILL[16] = {38, 38, 40, 38, 50, 48, 47, 45, 43, 41, 42, 42, 46, 39, 37, 36};
        uint32_t r, note;
        PKV(190) = PKV(190) * 1664525u + 1013904223u;
        r = PKV(190) >> 24;
        if (r < 40u) { /* (a rest now and then) */
            PKV(187) = 0;
            return;
        }
        note = r < 150u ? FILL[(PKV(190) >> 16) & 3u] /* the snare, most */
             : r < 215u ? FILL[4u + ((t->pfx_si + ((PKV(190) >> 16) & 1u)) % 6u)] /* toms, mostly downwards */
             : FILL[10u + ((PKV(190) >> 16) % 6u)];
        t->pfx_si++;
        seq_note_on(t, note, 60u + ((PKV(190) >> 8) & 63u) + (r & 1u ? 0u : 4u));
        t->pfx_sn[0] = (uint8_t)note;
        t->pfx_snn = 1;
    } else if (arp) {
        uint32_t k = t->pfx_si++ % (t->engine == 10u ? n : 3u * n);
        uint32_t note = t->pfx_ln[k % n] + 12u * (k / n);
        note = note > 127u ? 127u : note;
        seq_note_on(t, note, t->pfx_lv[k % n]);
        t->pfx_sn[0] = (uint8_t)note;
        t->pfx_snn = 1;
    } else {
        for (i = 0; i < n; i++) {
            seq_note_on(t, t->pfx_ln[i], t->pfx_lv[i]);
            t->pfx_sn[i] = t->pfx_ln[i];
        }
        t->pfx_snn = (uint8_t)n;
    }
    PKV(187) = 0;
}
