        uint32_t e = (2048u * (uint32_t)(s < 0 ? -s : s)) >> 8; /* the read point's sweep over a grain, Q8 */
        uint32_t ph = (PKV(117).gr_ph + j * 32768u) & 0xFFFFu, d, di, gl = dl;
        int32_t a, b, w;
        if (gl + PKV(117).gr_sp[j] > top) /* (JIANT 0.5) a long TIME (the whole line): */
            gl = top - PKV(117).gr_sp[j]; /* room for the sweep, else the read point sat clamped (no pitch).
                                                         * (0.6.19: each grain its own: grain 0's new spray moved grain 1's
                                                         * read point in the middle of its window: a click every grain) */
        d = ((gl + PKV(117).gr_sp[j]) << 8) + ((e * ((s > 0 ? 65535u - ph : ph) >> 4)) >> 12); /* Q8: up, the delay
                                                         * shrinks over the grain; down, it grows */
