    motion_restore(t);
    memcpy(PKV(293)[k], t->p, sizeof t->p);
    PKV(296) = (uint8_t)((PKV(296) & ~(1u << k)) | (PKV(5).playing ? 1u << k : 0u));
    motion_unguard(f);
