    motion_restore(t);
    for (i = 0; i < PKV(292).count; i++)
        if (((uint32_t)(&PKV(292).event[i])->place >> 6 | ((uint32_t)(((&PKV(292).event[i])->value >> 12) ^ ((&PKV(292).event[i])->value >> 15)) & 1u) << 2) != k) PKV(292).event[n++] = PKV(292).event[i];
