    for (i = 0; i < t->nheld; i++) {
        trk_note_off(t, t->held[i]);
        mo_key(t, 0x08u | (0x80u | trk_midi_ch(trk_index(t))) << 8 | (uint32_t)t->held[i] << 16);
    }
    t->nheld = 0;
