    const step_t *s;
    int32_t m;
    if (t->jump_to || t->rev || (!ni && (PKV(270).running || PKV(270).armed)))
        return 0;
    s = &seq_steps(t)[seq_src(t, ni)];
    if (s->time != ST_NOTE || (!s->n && !s->hit)) /* (nothing to play there: never early) */
        return 0;
