            *a = md <= 1u ? 0u : ((uint8_t)(((0u) & 15u) | ((md == 3u ? 1u : md == 5u ? 3u : 0u) & 3u) << 4 | ((md == 5u ? 1u : 0u) & 3u) << 6));
