    for (i = 0; i < 6; i++)
        seq_tick(&PKV(4)[i], seq_n);
    for (i = 0; i < 6; i++) /* (0.8.5) the kit's octaves held: their ratchets */
        if (PKV(318)[i])
            dxo_tick(&PKV(4)[i], clock_mode ? seq_n : n);
