    if (PKV(301) >= beat_samples()) {
        PKV(301) -= beat_samples();
        PKV(301) = PKV(301) < beat_samples() ? PKV(301) : 0u;
        PKV(302) = (PKV(302) + 1u) & 3u;
        if (!PKV(302) && PKV(5).playing)
            PKV(303)++;
    }
    if (PKV(5).playing)
        PKV(5).tick++;
