/* The song, the audio ISR's part (song_chain.c: what it is). Included at the end of seq.c. */
static uint32_t chain_bar(void) { return 16u * div_samples(2); } /* a 4/4 bar: 16 steps of 1/16 (DIV 2) */
/* the staged section in: every track from its step 0 (seq_tick: chain.carry samples into it) */
static void sec_apply(void)
{
    uint32_t i, j;
    for (i = 0; i < 6; i++) {
        track_t *t = &PKV(4)[i];
        const sec_trk_t *s = &PKV(269).t[i];
        seq_release(t);
        motion_restore(t);
        if (t->eng_req != s->engine)
            PKV(280) |= (uint8_t)(1u << i); /* (another engine: what the keys hold ends too) */
        t->eng_req = s->engine;
        t->preset = s->preset;
        t->user = 0;
        for (j = 0; j < P_COUNT; j++)
            t->p[j] = s->p[j];
        memcpy(t->step, s->step, sizeof t->step);
        memcpy(PKV(40)[i], s->fm6, FP_SIZE + 1u);
        PKV(41)[i]++;
        t->seq_idx = (uint16_t)(t->p[P_SLEN] - 1);
        t->seq_pos = 0x7FFFFFFFu;
        t->ext = 0;
        t->rh_n = t->rskip_n = 0;
        spill_stop(t); /* (0.9.18) a RATCH's spill: none into the new section */
    }
    PKV(292) = PKV(269).motion;
    memcpy(PKV(23), PKV(269).dx, sizeof PKV(23));
    dx_mute_set(PKV(269).dx_mute);
    memcpy(PKV(185), PKV(269).pfx_lane, sizeof PKV(185));
    memcpy(&PKV(5).g[G_SLMODE], PKV(269).slg, sizeof PKV(269).slg); /* (0.6.3) the SLICER's bus as the section has it */
    PKV(186) = PKV(269).pfx_ltgt;
    PKV(184) = 0; /* (the lane from the section's start) */
    memset(PKV(294), 0, sizeof PKV(294));
    memset(PKV(295), 0, sizeof PKV(295));
    PKV(296) = 0;
    PKV(271).cur = (int8_t)PKV(269).section;
    PKV(269).ready = 0;
    PKV(270).applied = 1;
}
/* (JIANT) the scene in effect onto what the section brought: its mutes; a row's own scene also the macros and the
 * punch-in effects (which nothing else sets) */
static void scene_apply(uint32_t row)
{
    const scene_t *s;
    uint32_t i;
    if (PKV(270).loop || row >= 16u)
        return; /* (a quick chain: no scenes) */
    if (PKV(267).scene[PKV(268)][row].on) {
        s = &PKV(267).scene[PKV(268)][row];
        PKV(270).scn = (uint8_t)(row + 1u);
        memcpy(PKV(69), s->mac, sizeof PKV(69));
        for (i = 0; i < 4u; i++)
            PKV(69)[i] &= 127u;
        PKV(167) = ((uint32_t)s->pfx << PF_OCTD) & (((1u << (PF_RND + 1)) - 1u) & ~((1u << PF_OCTD) - 1u));
    } else if (PKV(270).scn) {
        s = &PKV(267).scene[PKV(268)][PKV(270).scn - 1u];
    } else {
        return;
    }
    for (i = 0; i < 6; i++)
        PKV(4)[i].p[P_MUTE] = (int16_t)(i < 4u ? (s->mute >> i) & 1u : (s->on >> (i - 3u)) & 1u);
    dx_mute_set((uint16_t)((PKV(29) & ~DXG_ALL) | ((s->mute >> 4) & DXG_ALL)));
}
static void chain_apply(void) /* a song row's section in */
{
    PKV(270).row = PKV(269).row;
    PKV(270).remaining = PKV(270).config.row[PKV(270).row].bars;
    sec_apply();
    scene_apply(PKV(270).row);
}
/* SONG REC: a row for section s, its bars counted from 0 */
static void srec_finish(void)
{
    uint32_t i, n = 0;
    for (i = 0; i < PKV(271).nrec; i++)
        if (PKV(271).rec[i].bars) {
            PKV(271).rec_scene[n] = PKV(271).rec_scene[i];
            PKV(271).rec[n++] = PKV(271).rec[i];
        }
    PKV(271).rec_done = (uint8_t)(n ? n : 0xFFu);
    PKV(271).srec = 0;
    PKV(271).nrec = 0;
}
static void srec_add(uint32_t s)
{
    if (PKV(271).nrec >= 16u) {
        srec_finish(); /* full: what was played so far is the song */
        return;
    }
    PKV(271).rec[PKV(271).nrec].slot = (uint8_t)(s & 3u);
    PKV(271).rec[PKV(271).nrec].bars = 0;
    scene_capture(&PKV(271).rec_scene[PKV(271).nrec]); /* (JIANT: the row's scene, as it begins) */
    PKV(271).nrec++;
}
static void srec_bar(void) /* a bar ended */
{
    if (PKV(271).srec == 2u && PKV(271).nrec) {
        chain_row_t *e = &PKV(271).rec[PKV(271).nrec - 1u];
        if (e->bars < 64u) {
            e->bars++;
        } else { /* (64 bars of one section: it goes on in a new row) */
            srec_add(e->slot);
            if (PKV(271).srec == 2u)
                PKV(271).rec[PKV(271).nrec - 1u].bars = 1;
        }
    } else if (PKV(271).srec == 1u) { /* armed: it records from this bar */
        PKV(271).srec = 2;
        PKV(271).nrec = 0;
        srec_add(PKV(271).cur >= 0 ? (uint32_t)PKV(271).cur : 0u);
    }
}
static void srec_stop(void) /* SONG REC pressed again, or STOP: a begun bar counts */
{
    if (PKV(271).srec == 2u && PKV(271).nrec && PKV(270).bar_pos && PKV(271).rec[PKV(271).nrec - 1u].bars < 64u)
        PKV(271).rec[PKV(271).nrec - 1u].bars++;
    if (PKV(271).srec == 2u)
        srec_finish();
    PKV(271).srec = 0;
}
static void chain_start(void) /* (seq_start) */
{
    PKV(270).carry = 0;
    PKV(270).bar_pos = 0;
    PKV(270).armed_bar = 0;
    if (!PKV(270).armed)
        return;
    PKV(270).armed = 0;
    if (!PKV(269).ready || PKV(269).row != 0u)
        return; /* (cannot happen: chain_prepare staged row 0) */
    PKV(270).rec = PKV(5).rec;
    PKV(5).rec = 0; /* a song plays, it does not record */
    PKV(270).running = 1;
    PKV(270).scn = 0;
    chain_apply();
}
static void chain_stop(void) /* (seq_stop) */
{
    PKV(270).armed = 0;
    PKV(270).armed_bar = 0;
    PKV(271).req = -1;
    srec_stop();
    if (!PKV(270).running)
        return;
    PKV(5).rec = PKV(270).rec;
    PKV(270).running = 0;
    PKV(167) = 0; /* (a scene's punch-in effects end with the song) */
    PKV(270).ended = PKV(270).kept; /* (a quick chain keeps nothing: what plays stays) */
}
static void chain_tick(uint32_t n)
{
    uint32_t bar;
    if (!PKV(5).playing)
        return;
    bar = chain_bar();
    PKV(270).bar_pos += n;
    if (!bar || PKV(270).bar_pos < bar)
        return;
    PKV(270).bar_pos -= bar; /* (a bar is longer than a block) */
    PKV(270).carry = PKV(270).bar_pos;
    srec_bar();
    if (PKV(270).running) {
        uint32_t next = PKV(270).row + 1u;
        if (PKV(270).remaining > 1u) {
            PKV(270).remaining--;
            return;
        }
        if (next >= PKV(270).config.count) {
            uint32_t e = ((&PKV(270).config)->rsv[0]);
            if (!PKV(270).loop && !(e == 255u || (e >= 2u && PKV(270).pass + 1u < e))) { /* the song's end */
                seq_stop();
                return;
            }
            if (PKV(269).ready && PKV(269).row == 0u && !PKV(270).loop && PKV(270).pass < 254u)
                PKV(270).pass++; /* (0.6.22: its END: once more round) */
            next = 0; /* (a quick chain: round again) */
        }
        if (PKV(269).ready && PKV(269).row == next) {
            chain_apply(); /* (not staged yet: this row one bar more) */
            if (PKV(271).srec == 2u)
                srec_add(PKV(269).section);
        }
        return;
    }
    if (PKV(270).armed_bar && PKV(269).ready && PKV(269).row == 0u) { /* a quick chain from this bar */
        PKV(270).armed_bar = 0;
        PKV(270).running = 1;
        PKV(270).rec = PKV(5).rec;
        chain_apply();
        if (PKV(271).srec == 2u)
            srec_add(PKV(271).cur);
        return;
    }
    if (PKV(271).req >= 0 && PKV(269).ready && PKV(269).row == 0xFEu) { /* a live jump */
        PKV(271).req = -1;
        PKV(5).rec = 0; /* (a take does not run on into another section) */
        sec_apply();
        if (PKV(271).srec == 2u)
            srec_add(PKV(271).cur);
    }
}
static void host_tracks_init(void) /* as felucca_init: defaults, empty patterns */
{
    uint32_t i, k;
    for (i = 0; i < G_COUNT; i++)
        PKV(5).g[i] = GP[i].def;
    for (k = 0; k < 6; k++) {
        for (i = 0; i < P_E0; i++)
            PKV(4)[k].p[i] = TP[i].def;
        for (i = 0; i < 64; i++)
            PKV(4)[k].step[i].time = ST_REST;
    }
    PKV(5).master_q12 = 4096;
    if (!PKV(14))
        sing_init(); /* (0.9.0: as felucca_init, VOICE's English generator words) */
    PKV(95) = 6; /* (the tests play all six: TRACKS 6) */
}
static void host_preset_values(track_t *t, uint32_t e, uint32_t pi, const preset_t *p)
{
    static const uint8_t FX_DEF[4] = {0, 24, 28, 36};
    uint32_t i;
    t->eng_req = (uint8_t)e;
    t->preset = (uint8_t)pi;
    for (i = 0; i < 8u; i++)
        t->p[P_E0 + i] = p->e[i];
    t->p[P_ATK] = p->env[0];
    t->p[P_DEC] = p->env[1];
    t->p[P_SUS] = p->env[2];
    t->p[P_REL] = p->env[3];
    t->p[P_ED_FLT] = p->fenv;
    t->p[P_VOICE] = ((p)->mono & 1u) ? V_LEGATO : V_POLY;
    if (ENGINES[e] == &ENG_FORMANT) { /* (0.8.5) VOICE's words: LANG, LYRIC (ui.c apply_preset_to) */
        t->p[P_FM1_ATK] = (int16_t)(p->xp & 3u);
        t->p[P_FM3_REL] = (int16_t)(p->xp >> 2);
    }
    for (i = 0; i < 4u; i++)
        t->p[P_DIST + i] = (int16_t)(p->fx[i] ? p->fx[i] - 1 : FX_DEF[i]);
    fm6_track_loaded(t); /* FM6: the preset's patch (ui.c apply_preset_to) */
}
static void host_preset_req(track_t *t, uint32_t e, uint32_t pi)
{
    uint32_t n = ENGINES[e]->npresets;
    if (e == 1u) { /* DIGITAL preset pi (retired): converted, as ui.c fm4_load_preset */
        uint8_t v[FP_SIZE + 1u];
        uint32_t tr = (uint32_t)(t - PKV(4)) % 6;
        fm4_preset_values(t->p, pi);
        t->preset = (uint8_t)fm4_convert(t->p, v);
        t->eng_req = 12u;
        fm6_set_patch(tr, v);
        PKV(42)[tr] = (uint8_t)t->p[P_E7];
        return;
    }
    if (!n) {
        t->eng_req = (uint8_t)e;
        t->preset = 0;
        for (uint32_t i = 0; i < 8u; i++)
            t->p[P_E0 + i] = ENGINES[e]->edit[i].def;
        return;
    }
    pi %= n;
    host_preset_values(t, e, pi, &ENGINES[e]->presets[pi]);
}
static void host_preset(track_t *t, uint32_t e, uint32_t pi)
{
    host_preset_req(t, e, pi);
    t->engine = t->eng_req; /* (DIGITAL without FELUCCA_FM4: FM6) */
}
/* ------------------------------------------------------------------ Armada's glue (GPL-3.0-only, Gonzi Audio) --- */
enum { AG_NENGINES = 15, AG_CTL = 32 };
static void ag_init(void)
{
    uint32_t k;
    
    host_tracks_init();
    for (k = 1; k < 6; k++)
        PKV(4)[k].p[P_MUTE] = 1; /* the plugin plays part 1 */
    PKV(5).sel = 0;
}
static void ag_kill(void)
{
    uint32_t i;
    track_t *t = &PKV(4)[0];
    trk_all_off(t);
    for (i = 0; i < 8; i++) {
        t->v[i].active = t->v[i].gate = 0;
        t->v[i].stage = 0;
        t->v[i].env = t->v[i].env_out = 0;
    }
}
static void ag_sound(uint32_t e, uint32_t s)
{
    ag_kill();
    host_preset(&PKV(4)[0], e, s);
}
static const char *ag_own_name(uint32_t e, uint32_t s, uint32_t *count)
{
    (void)e; (void)s;
    *count = 0;
    return 0;
}
static int32_t ag_getp(uint32_t id) { return PKV(4)[0].p[id]; }
static void ag_setp(uint32_t id, int32_t v)
{
    const param_desc_t *d = &TP[id];
    PKV(4)[0].p[id] = (int16_t)(v < d->min ? d->min : v > d->max ? d->max : v);
}
static void ag_sete(uint32_t k, int32_t v)
{
    const param_desc_t *d = &ENGINES[PKV(4)[0].engine]->edit[k];
    PKV(4)[0].p[P_E0 + k] = (int16_t)(v < d->min ? d->min : v > d->max ? d->max : v);
}
static void ag_setg(uint32_t id, int32_t v)
{
    const param_desc_t *d = &GP[id];
    PKV(5).g[id] = (int16_t)(v < d->min ? d->min : v > d->max ? d->max : v);
}
static void ag_note_on(uint32_t n, uint32_t vel) { trk_note_on(&PKV(4)[0], n, vel); }
static void ag_note_off(uint32_t n) { trk_note_off(&PKV(4)[0], n); }
static void ag_all_off(void) { trk_all_off(&PKV(4)[0]); }
static void ag_bend(int32_t q8) { PKV(101)[0] = (q8); }
static void ag_render(int32_t *o, uint32_t n) { mix_block(o, n); }
static void ag_format(uint32_t e, uint32_t k, int32_t v, char *val, const char **unit)
{
    const param_desc_t *d = &ENGINES[e]->edit[k];
    *unit = 0;
    param_format(d, v, val, unit);
}

